using System;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class GodToolsChecks {
 static void Require(bool condition,string reason){if(!condition)throw new Exception(reason);}
 [MenuItem("BWVR/Verify summonable god tools (Play mode)")]
 public static void Verify(){
  Require(EditorApplication.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var palette=slice.GetComponentInChildren<GodToolPalette>();var god=slice.GetComponentInChildren<CreatureHybrid>();var miracles=slice.GetComponentInChildren<DivineIntervention>();var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)field.GetValue(slice);int initialUses=palette.Uses;var test=new SliceState{water=20,crops=40};god.Interrupt("God tools QA");field.SetValue(slice,test);var flags=BindingFlags.Instance|BindingFlags.NonPublic;var spot=(HybridTarget)typeof(GodToolPalette).GetField("spot",flags).GetValue(palette);var oldSpot=spot.transform.position;
  try{
   Require(miracles.tools.Count==5&&miracles.tools.TrueForAll(t=>!t.gameObject.activeInHierarchy),"Unrequested intention objects were pre-placed in the world");
   foreach(var kind in new[]{SpiritualTool.Help,SpiritualTool.Protect,SpiritualTool.Investigate,SpiritualTool.Rain,SpiritualTool.Heal}){palette.Select(kind);var symbol=(GameObject)typeof(GodToolPalette).GetField("wand",flags).GetValue(palette);Require(symbol.GetComponentsInChildren<MeshRenderer>(true).Length>0,"Hidden template lost palette symbol: "+kind);}palette.Cancel();
   miracles.ResetWorld();Require(!palette.Open&&!palette.Selected.HasValue,"Palette not hidden by default");palette.Toggle();Require(palette.Open&&palette.View.activeSelf,"Fallback did not open palette");Physics.SyncTransforms();
   var target=god.Find("cistern");var ray=new Ray(target.transform.position+Vector3.up*.5f,Vector3.down);palette.Process(ray,false,true,false,.02f,false);Physics.SyncTransforms();
   var choices=(Collider[])typeof(GodToolPalette).GetField("choices",flags).GetValue(palette);var eye=Camera.main;var selectionRay=new Ray(eye.transform.position,(choices[3].bounds.center-eye.transform.position).normalized);float energy=test.Hybrid.energy;palette.Process(selectionRay,true,true,false,.02f,false);Require(palette.Selected==SpiritualTool.Rain&&!palette.Open,"Physics pointer could not select rain button");
   palette.Process(ray,true,true,false,.02f,false);Require(test.Hybrid.energy==energy&&test.water==20,"Selection press cast a miracle");palette.Process(ray,false,true,false,.02f,false);palette.Process(ray,true,true,false,.02f,false);Require(test.Hybrid.energy==energy-35&&test.water==42&&palette.Uses==initialUses+1,"Trigger did not cast exact rain outcome/cost");palette.Process(ray,true,true,false,1,false);Require(palette.Uses==initialUses+1&&test.Hybrid.energy==energy-35,"Held trigger repeated cast");
   var pickup=typeof(QuestSlice).GetMethod("TryGrab",flags);Require(!(bool)pickup.Invoke(slice,new object[]{1,god.Find("object-3").GetComponent<CarryItem>()}),"Tool input also acquired a world object");
   int count=palette.Uses;Require(!palette.Apply(SpiritualTool.Heal,target,target.transform.position)&&palette.Uses==count&&test.Hybrid.energy==25,"Invalid heal spent energy");test.Hybrid.time+=1;var patient=god.Find("villager-2");patient.villager.Memory.injury=.35f;Require(palette.Apply(SpiritualTool.Heal,patient,patient.transform.position)&&test.Hybrid.energy==0&&patient.villager.Memory.injury==0&&test.water==42,"Healing affected wrong state");test.Hybrid.time+=1;Require(!palette.Apply(SpiritualTool.Rain,target,target.transform.position)&&test.water==42,"Unaffordable tool applied");
   var cue=god.Find("object-3");var before=test.Hybrid.guidance;Require(miracles.CanUse(SpiritualTool.Investigate,cue,out var reason)&&ReferenceEquals(before,test.Hybrid.guidance),"Preview mutated guidance");Require(palette.Apply(SpiritualTool.Investigate,cue,cue.transform.position)&&test.Hybrid.guidance.playerSign&&palette.Sign.activeSelf,"No physical guidance sign");Require(god.Owner==CreatureHybrid.ActionOwner.None,"Sign directly ordered motor action");
   var previous=test.Hybrid.guidance;Require(!palette.Apply(SpiritualTool.Protect,patient,patient.transform.position)&&ReferenceEquals(previous,test.Hybrid.guidance),"Invalid sign replaced active suggestion");
   var probe=(HybridTarget)typeof(GodToolPalette).GetField("probe",flags).GetValue(palette);probe.transform.position=god.transform.position;Require(palette.Apply(SpiritualTool.Investigate,probe,probe.transform.position)&&test.Hybrid.guidance.target==GodToolPalette.SpotId,"Reachable ground sign unsupported");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.Hybrid.guidance.playerSign,"Sign save invalid");field.SetValue(slice,saved);spot.transform.position=Vector3.zero;palette.RestoreSign();Require(Vector3.Distance(spot.transform.position,saved.Hybrid.guidance.spot)<.00001f&&palette.Sign.activeSelf,"Saved guidance point not restored");
   palette.ClearSign();Require(saved.Hybrid.guidance.status==GuidanceStatus.Abandoned&&!palette.Sign.activeSelf,"Sign removal left guidance active");
   saved.paused=true;float balance=saved.Hybrid.energy;Require(!palette.Apply(SpiritualTool.Investigate,cue,cue.transform.position)&&balance==saved.Hybrid.energy,"Pause allowed tool");saved.paused=false;
   palette.Select(SpiritualTool.Rain);palette.Process(ray,true,false,false,.02f,true);Require(!palette.Selected.HasValue&&!palette.View.activeSelf,"Tracking loss retained tool");palette.Process(ray,true,true,false,.02f,true);Require(palette.Uses==count+3,"Tracking restore replayed trigger");
   palette.Cancel();palette.Process(ray,false,true,false,.02f,false);Require(!palette.ClaimsInput,"Canceled tool blocked ordinary controls");
   palette.Toggle();palette.Process(ray,false,true,false,.02f,false);var fixedPoint=palette.View.transform.position;var facing=eye.transform.rotation;eye.transform.Rotate(0,20,0);palette.Process(ray,false,true,false,.02f,false);Require(Vector3.Distance(fixedPoint,palette.View.transform.position)<.00001f,"Desktop look dragged palette away from pointer");eye.transform.rotation=facing;palette.Cancel();palette.Process(ray,false,true,false,.02f,false);
   var left=(Transform)typeof(GodToolPalette).GetField("left",flags).GetValue(palette);var position=left.position;var rotation=left.rotation;try{left.position=eye.transform.position+eye.transform.forward*.3f;left.rotation=Quaternion.FromToRotation(Vector3.up,(eye.transform.position-left.position).normalized);palette.Wrist(.05f,true,true,false);left.rotation=Quaternion.FromToRotation(Vector3.up,(left.position-eye.transform.position).normalized);for(int i=0;i<8;i++)palette.Wrist(.05f,true,true,true);Require(!palette.Open,"Busy wrist revealed palette");for(int i=0;i<6;i++)palette.Wrist(.05f,true,true,false);Require(!palette.Open,"Wrist reveal ignored dwell");for(int i=0;i<2;i++)palette.Wrist(.05f,true,true,false);Require(palette.Open,"Intentional wrist did not reveal palette");left.rotation=rotation;palette.Wrist(.05f,true,true,false);Require(!palette.Open,"Wrist return did not dismiss gesture palette");}finally{left.SetPositionAndRotation(position,rotation);palette.Cancel();}
   palette.Process(ray,false,true,false,.02f,false);palette.Toggle();palette.Wrist(.02f,true,false,false);Require(!palette.Open,"Lost left tracking retained wrist palette");
   saved.Hybrid.guidance.spot=new Vector3(float.NaN,0,0);Require(!saved.Valid(),"Nonfinite sign position accepted");
   Debug.Log("BWVR_GOD_TOOLS_PASS: hidden palette/fallback; real physics-button selection; selection-release rearm; one rain per press; exact cost; heal target; invalid/poor/pause gates; nonmutating previews; autonomous signs; saved ground target; removal; tracking cleanup; restored input; desktop anchored aim; wrist dwell/busy/hysteresis; finite saves");
  }finally{god.Interrupt("God tools QA complete");field.SetValue(slice,original);spot.transform.position=oldSpot;palette.Cancel();palette.RestoreSign();miracles.Tick(0,false);god.NewSeason();}
 }
}
}
